-- Dorico bridge for sibelius-websocket-cli.
--
-- Dorico runs this through Script.RunScript. A request file generated by
-- dorico/bridge.py sets BRIDGE_REQUEST (a Lua table) and BRIDGE_RESPONSE (a
-- path), then runs this file. The answer is written to BRIDGE_RESPONSE as
-- JSON: {"ok": true, "result": ...} or {"ok": false, "error": "..."}.
--
-- Dorico's Lua API is undocumented (docs/dorico.md). What it relies on was
-- established by probing Dorico 6.2.30:
--   * DoCore.ScriptHost().currentScore is the open score; score, flow and
--     event members are luabind properties (field access), not methods.
--   * Every edit made during one script run is a single undo step.
--   * tostring() throws on some objects, so everything is wrapped in pcall.
--   * Units are quarter notes as rationals; the Python side uses 1/256 of a
--     quarter note, like the Sibelius bridge.

local BRIDGE_VERSION = 1
local UNITS = 256

---------------------------------------------------------------- JSON output

local ARRAY = {}
local function array(t) return setmetatable(t or {}, ARRAY) end

local ESCAPES = { ['"'] = '\\"', ['\\'] = '\\\\', ['\n'] = '\\n', ['\r'] = '\\r', ['\t'] = '\\t' }
local function quote(s)
  return '"' .. s:gsub('[%c"\\]', function(c)
    return ESCAPES[c] or string.format('\\u%04x', c:byte())
  end) .. '"'
end

local encode
local function encode_table(t)
  local n = #t
  local is_array = getmetatable(t) == ARRAY or n > 0
  local parts = {}
  if is_array then
    for i = 1, n do parts[i] = encode(t[i]) end
    return '[' .. table.concat(parts, ',') .. ']'
  end
  local keys = {}
  for k in pairs(t) do keys[#keys + 1] = tostring(k) end
  table.sort(keys)
  for _, k in ipairs(keys) do parts[#parts + 1] = quote(k) .. ':' .. encode(t[k]) end
  return '{' .. table.concat(parts, ',') .. '}'
end

encode = function(v)
  local kind = type(v)
  if v == nil then return 'null'
  elseif kind == 'boolean' then return v and 'true' or 'false'
  elseif kind == 'number' then
    if v ~= v or v == math.huge or v == -math.huge then return 'null' end
    if v == math.floor(v) and math.abs(v) < 2 ^ 53 then return string.format('%d', v) end
    return string.format('%.10g', v)
  elseif kind == 'string' then return quote(v)
  elseif kind == 'table' then return encode_table(v)
  end
  return quote(tostring(v))
end

---------------------------------------------------------------- helpers

local function str(v)
  local ok, s = pcall(tostring, v)
  if ok then return s end
  return '<' .. type(v) .. '>'
end

local function field(obj, name)
  local ok, v = pcall(function() return obj[name] end)
  if ok then return v end
  return nil
end

local function class_name(obj)
  local ok, info = pcall(class_info, obj)
  if ok and info then return str(info.name) end
  return type(obj)
end

-- Rational quarter-note values print as "1", "-3", "15/2 (7.5)" or "1/3 (0.333)".
local function fraction(r)
  if r == nil then return nil end
  local text = str(r)
  local n, d = text:match('^%s*(%-?%d+)/(%d+)')
  if n then return tonumber(n), tonumber(d) end
  n = text:match('^%s*(%-?%d+)')
  if n then return tonumber(n), 1 end
  return nil
end

-- A quarter-note rational in 1/256 units. Values that are not whole 1/256ths
-- (tuplets) are rounded; `exact` carries the true value as "n/d" quarters.
local function units(r)
  local n, d = fraction(r)
  if n == nil then return nil, str(r) end
  local value = n * UNITS / d
  if value == math.floor(value) then return value, nil end
  return math.floor(value + 0.5), n .. '/' .. d
end

local function length(u)
  return DoCore.RhythmicLength(u, UNITS)
end

-- A stream's events. Dorico throws "Not implemented" for streams holding
-- items its Lua layer cannot wrap (seen with an imported vocal score with
-- lyrics); that must not read as an empty stream.
local function stream_list(stream)
  local ok, events = pcall(function() return stream.events end)
  if not ok then
    error('Dorico cannot read the events in stream ' .. str(field(stream, 'id')) ..
      ' (its scripting does not support some item there, such as lyrics): ' .. str(events):sub(1, 80), 0)
  end
  local out = {}
  for _, v in pairs(events or {}) do out[#out + 1] = v end
  return out
end

local function list(t)
  local out = {}
  if type(t) ~= 'table' then return out end
  for _, v in pairs(t) do out[#out + 1] = v end
  return out
end

local function by_id(items)
  table.sort(items, function(a, b) return (field(a, 'id') or 0) < (field(b, 'id') or 0) end)
  return items
end

local CONTEXT = nil
local function context()
  if CONTEXT == nil then CONTEXT = DoCore.PropertyContext() end
  return CONTEXT
end

local function property(event, name)
  local table_ = field(event, 'propertyTable')
  if table_ == nil then return nil end
  local ok, v = pcall(function() return table_:get(name, context()) end)
  if not ok or v == nil or not field(v, 'valid') then return nil end
  local ok2, s = pcall(function() return v:toString() end)
  if ok2 then return s end
  return nil
end

---------------------------------------------------------------- score model

local function current_score()
  local score = field(DoCore.ScriptHost(), 'currentScore')
  if score == nil then error('no score is open in Dorico') end
  return score
end

local function flow_at(score, index)
  local flows = list(field(score, 'flows'))
  local flow = flows[index or 1]
  if flow == nil then error('the score has no flow ' .. tostring(index or 1) .. ' (it has ' .. #flows .. ')') end
  return flow, #flows
end

-- The flow's layout as Dorico's Lua exposes it, without guessing: stave
-- streams in id order, and instruments (in order) with their voice streams.
-- Lua has no link from a voice to its stave (docs/dorico.md), so
-- dorico/layout.py assigns voices to staves, from MusicXML when needed.
-- flow.instruments has one entry per voice, each listing all of that
-- instrument's voices, so entries are merged by instrument id.
local function raw_layout(score, flow)
  local names = {}
  for _, player in ipairs(list(field(score, 'players'))) do
    for _, instrument in ipairs(list(field(player, 'instruments'))) do
      names[field(instrument, 'id')] = str(player)
    end
  end
  local staves = array()
  for _, stave in ipairs(by_id(list(field(flow, 'staveStreams')))) do
    staves[#staves + 1] = { stream = field(stave, 'id') }
  end
  local instruments, seen = array(), {}
  for _, entry in ipairs(list(field(flow, 'instruments'))) do
    local iid = field(entry, 'id')
    if not seen[iid] then
      seen[iid] = true
      local voices = array()
      for _, v in ipairs(by_id(list(field(entry, 'streams')))) do voices[#voices + 1] = field(v, 'id') end
      instruments[#instruments + 1] = { id = iid, name = names[iid], voiceStreams = voices }
    end
  end
  return { staves = staves, instruments = instruments }
end

-- Events read from a stream report the base class Event to class_info, so
-- the type comes from the string form: "kNoteEvent (id:3) at 0, ..." for a
-- stream's events, "NoteEvent ID: 13" for one just created.
local function event_type(event)
  return str(event):match('^k?(%a+Event)') or class_name(event)
end

local function describe_event(event, staff, voice, stream_id)
  local kind = event_type(event)
  local item = { id = field(event, 'id'), type = kind, stream = stream_id, staff = staff, voice = voice }
  local position, exact = units(field(event, 'position'))
  item.position = position
  item.exactPosition = exact
  local duration, exact_duration = units(field(event, 'duration'))
  item.duration = duration
  item.exactDuration = exact_duration
  local text = str(event)
  if kind == 'NoteEvent' or kind == 'GraceNoteEvent' then
    item.pitch = tonumber(property(event, 'kNotePitch'))
    item.name = text:match('%s([A-G][#bx]*%-?%d+) %(ends') or text:match('%s([A-G][#bx]*%-?%d+)%s*$')
  elseif kind == 'ClefEvent' then
    item.clef = text:match('Clef entity ID in all layouts:%s*([%w%.]+)')
  elseif kind == 'TextEvent' then
    -- Read from a stream, a text event has no .text; its string form is
    -- "kTextEvent (id:33) at 12 : espr.\n (paragraph.defaulttext)".
    item.text = field(event, 'text')
    local body, style = text:match('^.-%sat%s[^:]-%s:%s(.*)\n%s*%(([%w%.]+)%)%s*$')
    if item.text == nil then item.text = body end
    item.style = style
  end
  return item
end

local function stream_events(stream, staff, voice, out)
  local sid = field(stream, 'id')
  for _, event in ipairs(stream_list(stream)) do
    out[#out + 1] = describe_event(event, staff, voice, sid)
  end
end

local function sort_events(events)
  table.sort(events, function(a, b)
    if (a.position or 0) ~= (b.position or 0) then return (a.position or 0) < (b.position or 0) end
    if (a.staff or 0) ~= (b.staff or 0) then return (a.staff or 0) < (b.staff or 0) end
    if (a.voice or 0) ~= (b.voice or 0) then return (a.voice or 0) < (b.voice or 0) end
    if (a.pitch or 0) ~= (b.pitch or 0) then return (a.pitch or 0) < (b.pitch or 0) end
    return (a.id or 0) < (b.id or 0)
  end)
  return array(events)
end

---------------------------------------------------------------- actions

local actions = {}

function actions.version()
  return { bridge = BRIDGE_VERSION, lua = _VERSION }
end

function actions.overview(request)
  local score = current_score()
  local flow, flow_count = flow_at(score, request.flow)
  local players = array()
  for _, p in ipairs(list(field(score, 'players'))) do players[#players + 1] = str(p) end
  local layouts = array()
  for _, l in ipairs(by_id(list(field(score, 'layouts')))) do layouts[#layouts + 1] = { id = field(l, 'id'), description = str(l) } end
  return {
    bridge = BRIDGE_VERSION,
    title = field(score, 'title'),
    openScoreID = field(score, 'openScoreID'),
    flow = request.flow or 1,
    flowCount = flow_count,
    players = players,
    layout = raw_layout(score, flow),
    layouts = layouts,
  }
end

-- Every event in the flow: the global timebase (time and key signature
-- events), stave streams (clefs and other staff items) and voice streams.
function actions.read(request)
  local score = current_score()
  local flow = flow_at(score, request.flow)
  local events = {}
  local unreadable = array()
  -- With skipUnreadable, streams Dorico cannot read (lyrics) are listed
  -- instead of failing the read, so bridge.py can fill them from MusicXML.
  local function add_stream(stream, staff, voice)
    if not request.skipUnreadable then return stream_events(stream, staff, voice, events) end
    local ok, problem = pcall(stream_events, stream, staff, voice, events)
    if not ok then unreadable[#unreadable + 1] = { stream = field(stream, 'id'), staff = staff, voice = voice } end
  end
  for _, tb in ipairs(list(field(flow, 'timebaseStreams'))) do add_stream(tb, 0, nil) end
  -- Stave-stream events get their stave's index; voice-stream events get
  -- none, since layout.py assigns voices to staves.
  for i, stave in ipairs(by_id(list(field(flow, 'staveStreams')))) do add_stream(stave, i, nil) end
  for _, voice in ipairs(by_id(list(field(flow, 'voiceStreams')))) do add_stream(voice, nil, nil) end
  return { flow = request.flow or 1, events = sort_events(events), unreadable = unreadable }
end

-- Bar lengths cannot be read (the time signature property does not convert),
-- so measure them: a bar rest created at a bar division takes that bar's
-- length. This edits the score, so bridge.py undoes it straight away and
-- checks the score matches what it read before.
function actions.bars(request)
  local score = current_score()
  local flow = flow_at(score, request.flow)
  local divisions = {}
  for _, tb in ipairs(list(field(flow, 'timebaseStreams'))) do
    for _, event in ipairs(stream_list(tb)) do
      if event_type(event) == 'BarDivisionEvent' then
        divisions[#divisions + 1] = { id = field(event, 'id'), position = units(field(event, 'position')) }
      end
    end
  end
  table.sort(divisions, function(a, b) return a.position < b.position end)
  -- Only voices Lua can read: a stream with lyrics cannot be measured in.
  local voices = {}
  for _, v in ipairs(list(field(flow, 'voiceStreams'))) do
    if pcall(stream_list, v) then voices[#voices + 1] = v end
  end
  -- An empty voice is the least disturbing place for a temporary bar rest.
  table.sort(voices, function(a, b) return #stream_list(a) < #stream_list(b) end)
  local probe = voices[1]
  if probe == nil then error('the flow has no voices to measure bars in') end
  local created = 0
  local out = array()
  -- Once anything is created the script is an undo step, so failures after
  -- that are reported rather than raised: bridge.py must still undo it.
  for _, d in ipairs(divisions) do
    local ok, rest = pcall(function() return probe:createBarRest(length(d.position)) end)
    if not ok or rest == nil then
      return { divisions = out, created = created, error = 'bar rest at ' .. d.position .. ': ' .. str(rest) }
    end
    created = created + 1
    local bar_length = units(field(rest, 'duration'))
    pcall(function() probe:delete(rest) end)
    out[#out + 1] = { position = d.position, length = bar_length, event = d.id }
  end
  return { divisions = out, created = created }
end

---------------------------------------------------------------- apply

local function find_event(stream, id)
  for _, event in ipairs(stream_list(stream)) do
    if field(event, 'id') == id then return event end
  end
  return nil
end

local function streams_by_id(score, flow)
  local map = {}
  for _, stream in ipairs(list(field(flow, 'allStreams'))) do map[field(stream, 'id')] = stream end
  return map
end

local function spelled(pitch, letter)
  return DoCore.MIDIPitchWithSpelling(DoCore.MIDIPitch(pitch), DoCore.NoteName.fromString(letter))
end

-- Check every addressed operation against the score before anything changes.
local function resolve(ops, streams)
  local targets = {}
  for i, op in ipairs(ops) do
    local label = 'op ' .. (i - 1)
    local stream = streams[op.stream]
    if stream == nil then return nil, label .. ': no stream ' .. tostring(op.stream) end
    if op.id ~= nil then
      local event = find_event(stream, op.id)
      if event == nil then return nil, label .. ': no event ' .. op.id .. ' in stream ' .. op.stream end
      local found = describe_event(event, nil, nil, op.stream)
      if op.type and found.type ~= op.type then
        return nil, label .. ': event ' .. op.id .. ' is a ' .. found.type .. ', not a ' .. op.type
      end
      if op.position and found.position ~= op.position then
        return nil, label .. ': event ' .. op.id .. ' is at ' .. tostring(found.position) .. ', not ' .. op.position
      end
      if op.oldPitch and found.pitch ~= op.oldPitch then
        return nil, label .. ': event ' .. op.id .. ' has pitch ' .. tostring(found.pitch) .. ', not ' .. op.oldPitch
      end
      targets[i] = { stream = stream, event = event, before = found }
    else
      targets[i] = { stream = stream }
    end
  end
  return targets
end

local apply_op = {}

apply_op['delete'] = function(op, t)
  if not t.stream:delete(t.event) then error('Dorico refused to delete event ' .. op.id) end
  return { before = t.before }
end

-- Dorico has no writable spelling, so a pitch change replaces the note with a
-- new one spelled as asked. The replacement gets a new event id.
apply_op['set-pitch'] = function(op, t)
  local position = field(t.event, 'position')
  local duration = field(t.event, 'duration')
  if not t.stream:delete(t.event) then error('Dorico refused to delete event ' .. op.id) end
  local note = t.stream:createNote(position, duration, spelled(op.newPitch, op.letter))
  return { before = t.before, after = describe_event(note, nil, nil, op.stream) }
end

apply_op['add-note'] = function(op, t)
  local after = array()
  for i, pitch in ipairs(op.pitches) do
    local note = t.stream:createNote(length(op.position), length(op.duration), spelled(pitch, op.letters[i]))
    after[#after + 1] = describe_event(note, nil, nil, op.stream)
  end
  return { after = after }
end

apply_op['add-rest'] = function(op, t)
  local rest = t.stream:createRest(length(op.position), length(op.duration))
  return { after = describe_event(rest, nil, nil, op.stream) }
end

apply_op['add-text'] = function(op, t)
  local text = t.stream:createText(length(op.position), length(op.duration or 0), op.text)
  return { after = describe_event(text, nil, nil, op.stream) }
end

-- Clefs live in the staff's stave stream, and their kind is a clef library
-- entity such as clef.treble or clef.bass (score.libraries.clefs).
apply_op['add-clef'] = function(op, t)
  local entity = current_score().libraries.clefs:find(op.clef)
  if entity == nil then error('no clef ' .. op.clef .. ' in the score library') end
  local clef = t.stream:createClef(length(op.position), length(0), false, entity)
  return { after = describe_event(clef, nil, nil, op.stream) }
end

function actions.apply(request)
  local score = current_score()
  local flow = flow_at(score, request.flow)
  local ops = request.operations or {}
  local targets, problem = resolve(ops, streams_by_id(score, flow))
  if targets == nil then return { error = problem, applied = 0 } end
  if request.dryRun then
    local checked = array()
    for i, t in ipairs(targets) do checked[#checked + 1] = { op = ops[i].op, before = t.before } end
    return { dryRun = true, applied = 0, results = checked }
  end
  local results = array()
  for i, op in ipairs(ops) do
    local handler = apply_op[op.op]
    if handler == nil then return { error = 'op ' .. (i - 1) .. ': unknown op ' .. tostring(op.op), applied = i - 1, results = results } end
    local ok, result = pcall(handler, op, targets[i])
    if not ok then
      return { error = 'op ' .. (i - 1) .. ' (' .. op.op .. '): ' .. str(result), applied = i - 1, results = results }
    end
    result.op = op.op
    results[#results + 1] = result
  end
  return { applied = #ops, results = results }
end

function actions.save(request)
  local score = current_score()
  if not DoApp.DoApp():save(score, request.path) then error('Dorico did not save to ' .. request.path) end
  return { path = request.path }
end

---------------------------------------------------------------- entry point

local function respond(payload)
  local tmp = BRIDGE_RESPONSE .. '.tmp'
  local handle = assert(io.open(tmp, 'w'))
  handle:write(encode(payload))
  handle:close()
  assert(os.rename(tmp, BRIDGE_RESPONSE))
end

local request = BRIDGE_REQUEST or {}
local handler = actions[request.action]
if handler == nil then
  respond({ ok = false, error = 'unknown bridge action: ' .. tostring(request.action) })
else
  local ok, result = xpcall(function() return handler(request) end, debug.traceback)
  if ok then respond({ ok = true, result = result }) else respond({ ok = false, error = str(result) }) end
end
